function addRiServiceGeometry(feature,district,riName,type,scheduleByDay,riCode=''){
  const g=feature.geometry;if(!g)return;
  const multi=g.type==='Polygon'?[g.coordinates]:(g.type==='MultiPolygon'?g.coordinates:[]);
  const label=type==='general'?'생활쓰레기':'재활용쓰레기';
  const displayRi=verifiedRiDisplayName(district,riName,riCode);
  const baseColor=type==='general'?'#6f9d87':'#7e97bd';

  multi.forEach(polyCoords=>{
    if(!polyCoords.length)return;
    const paths=polyCoords.map(ring=>ring.map(([lng,lat])=>new kakao.maps.LatLng(lat,lng)));
    const polygon=new kakao.maps.Polygon({
      path:paths.length===1?paths[0]:paths,
      strokeWeight:1,
      strokeColor:'#475569',
      strokeOpacity:.72,
      fillColor:baseColor,
      fillOpacity:.035
    });
    polygon.setMap(null);

    kakao.maps.event.addListener(polygon,'mouseover',(mouseEvent)=>{
      polygon.setOptions({fillOpacity:.08,strokeOpacity:.95});
      showZoneTooltip(
        mouseEvent.latLng,
        `${district} ${displayRi}`,
        `${label} · 법정리 경계`,
        '① 법정리 경계 레이어 · 일정판정은 ② 수거권역 사용'
      );
    });
    kakao.maps.event.addListener(polygon,'mousemove',e=>moveZoneTooltip(e.latLng));
    kakao.maps.event.addListener(polygon,'mouseout',()=>{
      polygon.setOptions({fillOpacity:.035,strokeOpacity:.72});
      hideZoneTooltip();
    });
    kakao.maps.event.addListener(polygon,'click',()=>{
      updateMapBadge(`${district} ${displayRi} · ① 법정리 경계입니다. 주소 수거요일은 ② 수거권역 포함 여부로 판정하고, ③ 근거노선으로 판단 근거를 확인할 수 있습니다.`);
    });

    // scheduleByDay는 주소 카드 판정에 사용하지 않습니다.
    zonePolygons[type].push({
      polygon,district,ri:riName,riCode,displayRi,
      scheduleByDay:{},kind:'ri-boundary',unassigned:false
    });
  });
}

