  rings.forEach(r=>r.forEach(p=>{const lng=+p[0],lat=+p[1];if(!Number.isFinite(lng)||!Number.isFinite(lat))return;minLng=Math.min(minLng,lng);maxLng=Math.max(maxLng,lng);minLat=Math.min(minLat,lat);maxLat=Math.max(maxLat,lat)}));
